def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_def = opp.count('D')
    my_def = my.count('D')
    last_my, last_opp = history[-1]

    # Early game: cooperate, but retaliate immediately if opponent defects.
    if n < 15:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Probe at round 16 (n=15): defect once, then cooperate to test retaliation.
    if n == 15:
        return 'D'
    if n == 16:
        return 'C'

    # Check if opponent retaliated to the probe.
    strict = False
    if n >= 17:
        if history[16][1] == 'D':
            strict = True

    # Strict retaliator: play TFT with last round defection.
    if strict:
        if last_opp == 'D':
            if last_my == 'D' and opp_def < n * 0.3:
                return 'C'
            return 'D'
        else:
            if n >= 99:
                return 'D'
            return 'C'

    # Non-strict: opponent is forgiving.
    # Last round always defect.
    if n >= 99:
        return 'D'

    # TFT with forgiveness for non-strict opponents.
    if last_opp == 'D':
        if last_my == 'D':
            if opp_def < n * 0.3:
                return 'C'
            return 'D'
        else:
            return 'D'

    # Opponent cooperated last round.
    # Endgame exploitation: from n=70 to n=98, defect on alternating rounds.
    # Only if opponent has been very cooperative (low defection rate).
    if n >= 70 and n <= 98:
        if opp_def < n * 0.15:
            if n % 2 == 0:
                return 'D'
            return 'C'

    return 'C'
